const input = $json || {};
const safeParse = (value, fallback) => {
  if (value === undefined || value === null || value === '') return fallback;
  if (typeof value === 'object') return value;
  try { return JSON.parse(value); } catch { return fallback; }
};

const context = safeParse(input.context_json, {});
const successCriteria = safeParse(input.success_criteria_json, []);
const taskKind = String(input.task_kind || 'assistant_improvement');
const userRequest = String(input.user_request || '').trim();
const endpoint = String(input.endpoint || $env.GENSPARK_CHAT_COMPLETIONS_URL || 'https://api.genspark.ai/chat/completions');
const model = String(input.model || $env.GENSPARK_MODEL || 'gemini-2.5-pro');

if (!userRequest) {
  return [{
    json: {
      status: 'needs_input',
      summary: 'Пустой запрос для Genspark delegate',
      artifacts: [],
      verification: { result: 'fail', tests_run: [] },
      next_action: 'Передай user_request в sub-workflow',
      delegate_meta: { task_kind: taskKind, delegated: false }
    }
  }];
}

return [{
  json: {
    task_kind: taskKind,
    user_request: userRequest,
    context,
    success_criteria: Array.isArray(successCriteria) ? successCriteria : [String(successCriteria)],
    endpoint,
    model
  }
}];

const item = $json;
const system = [
  'Ты внешний engineering-agent для Telegram personal assistant на n8n.',
  'Работай как исполнитель задачи по улучшению ассистента.',
  'Отвечай только JSON-объектом.',
  'Схема ответа:',
  '{"status":"done|needs_input|failed","summary":"string","artifacts":[{"type":"string","path":"string","description":"string"}],"verification":{"result":"pass|partial|fail","tests_run":["string"]},"next_action":"string|null"}',
  'Если данных не хватает — верни status=needs_input.',
  'Если задачу нельзя завершить полностью без внешнего действия — верни partial/fail и опиши next_action.',
  'Не используй markdown fences.'
].join(' ');

const userPayload = {
  task_kind: item.task_kind,
  user_request: item.user_request,
  success_criteria: item.success_criteria,
  context: item.context,
};

const requestBody = {
  model: item.model,
  temperature: 0.2,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: JSON.stringify(userPayload) }
  ]
};

return [{
  json: {
    endpoint: item.endpoint,
    requestBody,
    task_kind: item.task_kind,
    user_request: item.user_request,
    success_criteria: item.success_criteria,
    context: item.context
  }
}];

const raw = $json;
const extract = () => {
  if (raw.choices?.[0]?.message?.content) return raw.choices[0].message.content;
  if (typeof raw.output_text === 'string') return raw.output_text;
  if (typeof raw.content === 'string') return raw.content;
  return JSON.stringify(raw);
};

let text = extract();
text = String(text || '').trim();
text = text.replace(/^```json\s*/i, '').replace(/^```/, '').replace(/```$/, '').trim();

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = {
    status: 'failed',
    summary: 'Не удалось распарсить ответ Genspark как JSON',
    artifacts: [],
    verification: { result: 'fail', tests_run: [] },
    next_action: 'Проверить endpoint/формат ответа Genspark',
    raw_text: text.slice(0, 4000)
  };
}

if (!parsed.status) parsed.status = 'done';
if (!parsed.summary) parsed.summary = 'Genspark delegate вернул ответ без summary';
if (!Array.isArray(parsed.artifacts)) parsed.artifacts = [];
if (!parsed.verification || typeof parsed.verification !== 'object') parsed.verification = { result: 'partial', tests_run: [] };
if (!Array.isArray(parsed.verification.tests_run)) parsed.verification.tests_run = [];
if (!('next_action' in parsed)) parsed.next_action = null;

return [{ json: parsed }];
